(()=>{
 const login=document.querySelector('#loginForm'),email=document.querySelector('#email');email.value='';email.placeholder='Email admin Anda';
 login.addEventListener('submit',event=>{event.stopImmediatePropagation();event.preventDefault();secureLogin(event)},true);
 async function secureLogin(event){const button=event.submitter;button.disabled=true;try{await api('/api/session',{method:'POST',body:JSON.stringify({email:email.value,password:document.querySelector('#password').value})});document.querySelector('#loginScreen').classList.add('hidden');await loadData();toast('Login berhasil')}catch(error){toast(error.message)}finally{button.disabled=false}}
 login.querySelector('.hint').textContent='Gunakan email admin dan kata sandi toko.';
 const forgot=document.createElement('button');forgot.type='button';forgot.className='link-btn';forgot.textContent='Lupa kata sandi?';login.append(forgot);
 forgot.addEventListener('click',async()=>{if(!email.reportValidity())return;forgot.disabled=true;try{const response=await fetch('/api/admin/password-reset/request',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:email.value})}),data=await response.json();if(!response.ok)throw new Error(data.error);toast(data.message)}catch(error){toast(error.message)}finally{forgot.disabled=false}});
 const token=new URLSearchParams(location.search).get('reset');if(!token)return;
 const panel=document.createElement('section');panel.className='login';panel.style.zIndex='11';panel.innerHTML='<form class="login-card"><h1>Kata sandi admin baru</h1><p>Minimal 12 karakter. Semua sesi admin akan diakhiri.</p><div class="field"><label>Kata sandi baru</label><input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div><div class="field"><label>Konfirmasi kata sandi</label><input name="confirm" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div><p role="status"></p><button class="primary" type="submit">Simpan kata sandi</button></form>';document.body.append(panel);history.replaceState(null,'',location.pathname);
 panel.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const response=await fetch('/api/admin/password-reset/confirm',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token,newPassword:panel.querySelector('[name=password]').value,confirmPassword:panel.querySelector('[name=confirm]').value})}),data=await response.json();if(!response.ok)throw new Error(data.error);panel.remove();showLogin();toast('Kata sandi diganti. Silakan login kembali.')}catch(error){panel.querySelector('[role=status]').textContent=error.message}finally{button.disabled=false}});
})();
